// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
// import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
// import "./PropertyShareToken.sol";
import "../token/Token.sol";

contract FractionalMarketplace is ReentrancyGuard {
    struct PropertyListing {
        address propertyToken; 
        address owner;
        uint256 totalTokens;
        uint256 pricePerToken;
        uint256 remainingTokens;
        bool active; 
        uint256 tokenId;
        uint256 incomeBalance;
        bool buyBack;
        uint256 buyBackPrice;
    }

    IERC20 public stablecoin;
    address public authority;

    mapping(uint256 => PropertyListing) public listings;
    mapping(uint256 => uint256) public incomeSnapshots; 
    mapping(uint256 => mapping(address => uint256)) public claimedIncome;
    // mapping(uint256 => uint256) public ownerWithdrawableBalance;

    event PropertyListed(uint256 indexed tokenId, address indexed owner, address propertyToken, uint256 totalTokens);
    event TokensBought(uint256 indexed tokenId, address indexed buyer, uint256 amount, uint256 totalPrice);
    event ListingCancelled(uint256 indexed tokenId, address indexed owner, uint256 unsoldTokens);
    event PriceUpdated(uint256 indexed tokenId, uint256 newPricePerToken);
    event IncomeDeposited(uint256 indexed tokenId, uint256 amount, uint256 snapshotId);
    event IncomeClaimed(uint256 indexed tokenId, address indexed user, uint256 amount);
    event FractionsAdded(uint256 indexed tokenId, address indexed user, uint256 amount);
    event OwnerWithdrawn(uint256 indexed tokenId, address indexed owner, uint256 amount);
    event BuyBackActivated(uint256 indexed tokenId,uint256 buyBackPrice);
    event TokenRecieved(uint256 indexed tokenId, address indexed user,uint256 amount);

    constructor(address _stablecoin, address _authority) {
        stablecoin = IERC20(_stablecoin);
        authority = _authority;
    }

    // List tokens for sale
    function listProperty(address propertyToken, uint256 totalTokens) external {
        require(totalTokens > 0, "Must list non-zero tokens");
        require(IERC20(propertyToken).allowance(msg.sender, address(this)) >= totalTokens, "Approve tokens first");
        uint256 tokenId = Token(propertyToken).getTokenId();

        PropertyListing storage listing = listings[tokenId];
        require(listing.propertyToken == address(0) || !listing.active, "Listing already active");

        listings[tokenId] = PropertyListing({
            propertyToken: propertyToken,
            owner: msg.sender,
            totalTokens: totalTokens,
            pricePerToken: 40000000,
            remainingTokens: totalTokens,
            active: true,
            tokenId: tokenId,
            incomeBalance: 0,
            buyBack: false,
            buyBackPrice: 0
        });

        IERC20(propertyToken).transferFrom(msg.sender, address(this), totalTokens);
        emit PropertyListed(tokenId, msg.sender, propertyToken, totalTokens);
    }

    // Add tokens to an existing listing
    function addTokensToListing(uint256 tokenId, uint256 additionalTokens) external {
        PropertyListing storage listing = listings[tokenId];
        require(listing.active, "Listing not active");
        require(msg.sender == listing.owner, "Only owner can add tokens");
        require(IERC20(listing.propertyToken).allowance(msg.sender, address(this)) >= additionalTokens, "Approve tokens first");

        IERC20(listing.propertyToken).transferFrom(msg.sender, address(this), additionalTokens);

        listing.totalTokens += additionalTokens;
        listing.remainingTokens += additionalTokens;
        emit FractionsAdded(tokenId, msg.sender, additionalTokens);
    }

    // Users buy tokens
    function buyTokens(uint256 tokenId, uint256 amount) external nonReentrant {
        PropertyListing storage listing = listings[tokenId];
        require(listing.active, "Inactive listing");
        require(amount <= listing.remainingTokens, "Not enough tokens");
        require(amount > 0, "Must buy non-zero tokens");
        require(listing.buyBack == false, "Delisting Active");

        uint256 totalPrice = (amount * listing.pricePerToken) / 1e18;
        stablecoin.transferFrom(msg.sender, listing.owner, totalPrice);

        IERC20(listing.propertyToken).transfer(msg.sender, amount);
        listing.remainingTokens -= amount;

        if (listing.remainingTokens == 0) {
            listing.active = false;
        }
        emit TokensBought(tokenId, msg.sender, amount, totalPrice);
    }

    // Owner cancels listing
    function cancelListing(uint256 tokenId) external {
        PropertyListing storage listing = listings[tokenId];
        require(msg.sender == listing.owner, "Not owner");
        require(listing.active, "Already inactive");
        require(listing.remainingTokens == listing.totalTokens,"Insufficient Tokens");
        listing.active = false;
        listing.buyBack = false;
        uint256 unsoldTokens = listing.remainingTokens;
        listing.remainingTokens = 0;

        if (unsoldTokens > 0) {
            IERC20(listing.propertyToken).transfer(msg.sender, unsoldTokens);
        }
        emit ListingCancelled(tokenId, msg.sender, unsoldTokens);
    }

    // Update price
    function updatePropertyPrice(uint256 tokenId, uint256 newPricePerToken) external {
        PropertyListing storage listing = listings[tokenId];
        require(listing.active, "Listing not active");
        require(msg.sender == listing.owner || msg.sender == authority, "Not authorized");
        require(newPricePerToken > 0, "Price must be non-zero");

        listing.pricePerToken = newPricePerToken;
        emit PriceUpdated(tokenId, newPricePerToken);
    }

    function activateBuyBack(uint256 tokenId, uint256 buyBackPrice) external {
        PropertyListing storage listing = listings[tokenId];
        require(listing.active, "Listing not active");
        require(buyBackPrice > 0, "Amount must be > 0");
        require(listing.buyBack == false,"Buyback Already Active");
        require(msg.sender == listing.owner,"Not owner;");

        uint256 minimumBuyBackPrice = (listing.pricePerToken * 110) / 100;
        require(buyBackPrice >= minimumBuyBackPrice, "BuybackPrice Min 10%");

        listing.buyBackPrice = buyBackPrice;
        listing.buyBack = true;
        emit BuyBackActivated(tokenId, buyBackPrice);
    }

    function sellTokensBack(uint256 tokenId, uint256 amount) external nonReentrant {
        PropertyListing storage listing = listings[tokenId];
        require(listing.active, "Listing not active");
        require(amount > 0, "Amount must be > 0");
        require(listing.buyBack == true,"Activate Listing");

        uint256 refundAmount = (amount * listing.buyBackPrice) / 1e18;

        require(stablecoin.allowance(listing.owner, address(this)) >= refundAmount, "Owner must approve stablecoin transfer");
        require(IERC20(listing.propertyToken).allowance(msg.sender, address(this)) >= amount, "Approve token transfer first");

        IERC20(listing.propertyToken).transferFrom(msg.sender, address(this), amount);

        stablecoin.transferFrom(listing.owner, msg.sender, refundAmount);

        listing.remainingTokens += amount;

        emit TokenRecieved(tokenId, msg.sender, amount);

        }


    // Deposit income for distribution Undre development
    // function depositIncome(uint256 tokenId, uint256 amount) external nonReentrant {
    //     PropertyListing storage listing = listings[tokenId];
    //     require(listing.active || listing.totalTokens > 0, "Invalid listing");
    //     require(msg.sender == listing.owner || msg.sender == authority, "Not authorized");
    //     require(amount > 0, "Must deposit non-zero amount");

    //     stablecoin.transferFrom(msg.sender, address(this), amount);
    //     listing.incomeBalance += amount;
    //     uint256 snapshotId = Token(listing.propertyToken).snapshot();
    //     incomeSnapshots[tokenId] = snapshotId;

    //     emit IncomeDeposited(tokenId, amount, snapshotId);
    // }

    // Claim income based on token holdings under development
    // function claimIncome(uint256 tokenId) external nonReentrant {
    //     PropertyListing storage listing = listings[tokenId];
    //     uint256 snapshotId = incomeSnapshots[tokenId];
    //     require(snapshotId > 0, "No distribution available");

    //     uint256 balanceAtSnapshot = Token(listing.propertyToken).balanceOfAt(msg.sender, snapshotId);
    //     uint256 totalSupply = Token(listing.propertyToken).totalSupply();
    //     uint256 claimable = (balanceAtSnapshot * listing.incomeBalance) / totalSupply;

    //     require(claimable > 0, "No income to claim");
    //     require(claimedIncome[tokenId][msg.sender] == 0, "Already claimed");

    //     claimedIncome[tokenId][msg.sender] = claimable;
    //     listing.incomeBalance -= claimable;
    //     stablecoin.transfer(msg.sender, claimable);

    //     emit IncomeClaimed(tokenId, msg.sender, claimable);
    // }
}

